SET
  @Name_627a8792cd5e = N'Check Entitlement'
SET
  @OperationKey_627a8792cd5e = N'Orders.CheckEntitlement'
SET
  @CategoryID_627a8792cd5e = 'B1C4E2A0-6F3D-4A18-9E52-7C0D5A81B306'
SET
  @Description_627a8792cd5e = N'Does this person currently have this entitlement? Asked by Code (the capability), not SKU. PersonID is authoritative; email is a convenience, resolved to one Person by the same rule the checkout uses when several share it (Orders history, then oldest). Access is evaluated (status + window + subscription access-through), never read off EntitlementGrant.Status. Unknown person and known person without access return the same shape. Fail closed. v1 evaluates person grants only.'
SET
  @InputTypeName_627a8792cd5e = N'CheckEntitlementInput'
SET
  @InputTypeDefinition_627a8792cd5e = N'/**
 * Input for `Orders.CheckEntitlement`.
 *
 * Asked by capability Code, not SKU. PersonID is authoritative; email is a convenience
 * resolution (normalised; several Persons sharing it resolve by the checkout''s rule). AsOf is diagnostics only (historical
 * audit). The trust path omits it. Future values are rejected. CacheUntil is always
 * issued from wall-clock now, never from AsOf.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export interface CheckEntitlementInput {
    /** Authoritative person key. When present, Email is ignored. */
    PersonID?: string;
    /** Convenience. Normalised; several matching Persons resolve to one by `ResolvePersonByEmail` (Orders history, then oldest). */
    Email?: string;
    /** `ProductEntitlement.Code` — unique per product, not globally. Convention: APP_AREA_TIER. */
    Code: string;
    /** Diagnostics only (historical audit). Omit on the trust path. Future values are rejected. */
    AsOf?: string;
    /** Optional narrowing via the template product''s company. */
    CompanyID?: string;
}
'
SET
  @InputTypeIsArray_627a8792cd5e = 0
SET
  @OutputTypeName_627a8792cd5e = N'CheckEntitlementOutput'
SET
  @OutputTypeDefinition_627a8792cd5e = N'/**
 * Output for `Orders.CheckEntitlement`.
 *
 * `Decision` is why, not just whether — expired, revoked, never bought, and not-yet-valid
 * are three screens. Unknown person and known-person-without-access share this shape
 * (`HasAccess: false`, `Decision: ''NoGrant''`). Dates are ISO strings.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export type EntitlementDecision =
    | ''Granted''
    | ''NoGrant''
    | ''NotYetValid''
    | ''Expired''
    | ''Revoked''
    | ''Suspended''
    | ''SubscriptionInactive'';

/**
 * Why a grant is suspended: waiting for its first payment (a new purchase), past due beyond the
 * renewal cutoff, or waiting for activation.
 */
export type EntitlementSuspensionReason = ''AwaitingPayment'' | ''PastDue'' | ''AwaitingActivation'';

export interface CheckEntitlementOutput {
    HasAccess: boolean;
    Decision: EntitlementDecision;
    ValidFrom?: string;
    /** When access actually ends — grant window, or subscription access-through after cancel. */
    ValidTo?: string;
    /** ResourceQuantity — seats. Null for Feature/AccessLevel. */
    Quantity?: number;
    /** Audit handle of the winning grant. */
    GrantID?: string;
    /** Present only with `Decision: ''Suspended''`: why access is held. Null when no reason is recorded (a suspension a person made). */
    SuspensionReason?: EntitlementSuspensionReason | null;
    /**
     * Present only while access holds on a renewal that is past due: the last day (`YYYY-MM-DD`, business
     * time zone) access is kept before the past-due cutoff suspends it, or an approved cutoff deferral''s
     * last day when that is later.
     */
    AccessCutoffDate?: string;
    EvaluatedAt: string;
    /** min(ValidTo, wall-clock now + 60s). Never derived from AsOf. Fail closed when stale. */
    CacheUntil: string;
}
'
SET
  @OutputTypeIsArray_627a8792cd5e = 0
SET
  @ExecutionMode_627a8792cd5e = N'Sync'
SET
  @RequiredScope_627a8792cd5e = N'orders:entitlement-check'
SET
  @RequiresSystemUser_627a8792cd5e = 0
SET
  @GenerationType_627a8792cd5e = N'Manual'
SET
  @CodeApprovalStatus_627a8792cd5e = N'Approved'
SET
  @Status_627a8792cd5e = N'Active'
SET
  @CodeLocked_627a8792cd5e = 0
SET
  @ID_627a8792cd5e = 'C2D5F3B1-7E4A-4B29-8F63-1D2E6B92C420'
SELECT TOP 1 @ID_627a8792cd5e = [ID] FROM [${mjSchema}].[RemoteOperation] WHERE [OperationKey] = N'Orders.CheckEntitlement' ORDER BY CASE WHEN [ID] = @ID_627a8792cd5e THEN 0 ELSE 1 END
SELECT TOP 1 @CategoryID_627a8792cd5e = [ID] FROM [${mjSchema}].[RemoteOperationCategory] WHERE [Name] = N'Entitlements' ORDER BY CASE WHEN [ID] = @CategoryID_627a8792cd5e THEN 0 ELSE 1 END
EXEC [${mjSchema}].spUpdateRemoteOperation @Name = @Name_627a8792cd5e,
  @OperationKey = @OperationKey_627a8792cd5e,
  @CategoryID = @CategoryID_627a8792cd5e,
  @Description = @Description_627a8792cd5e,
  @InputTypeName = @InputTypeName_627a8792cd5e,
  @InputTypeDefinition = @InputTypeDefinition_627a8792cd5e,
  @InputTypeIsArray = @InputTypeIsArray_627a8792cd5e,
  @OutputTypeName = @OutputTypeName_627a8792cd5e,
  @OutputTypeDefinition = @OutputTypeDefinition_627a8792cd5e,
  @OutputTypeIsArray = @OutputTypeIsArray_627a8792cd5e,
  @ExecutionMode = @ExecutionMode_627a8792cd5e,
  @RequiredScope = @RequiredScope_627a8792cd5e,
  @RequiresSystemUser = @RequiresSystemUser_627a8792cd5e,
  @GenerationType = @GenerationType_627a8792cd5e,
  @Code = @Code_627a8792cd5e,
  @Code_Clear = 1,
  @CodeApprovalStatus = @CodeApprovalStatus_627a8792cd5e,
  @CodeApprovedByUserID = @CodeApprovedByUserID_627a8792cd5e,
  @CodeApprovedByUserID_Clear = 1,
  @CodeApprovedAt = @CodeApprovedAt_627a8792cd5e,
  @CodeApprovedAt_Clear = 1,
  @ContractFingerprint = @ContractFingerprint_627a8792cd5e,
  @ContractFingerprint_Clear = 1,
  @Status = @Status_627a8792cd5e,
  @CacheTTLSeconds = @CacheTTLSeconds_627a8792cd5e,
  @CacheTTLSeconds_Clear = 1,
  @TimeoutMS = @TimeoutMS_627a8792cd5e,
  @TimeoutMS_Clear = 1,
  @MaxConcurrency = @MaxConcurrency_627a8792cd5e,
  @MaxConcurrency_Clear = 1,
  @CodeLocked = @CodeLocked_627a8792cd5e,
  @CodeComments = @CodeComments_627a8792cd5e,
  @CodeComments_Clear = 1,
  @Libraries = @Libraries_627a8792cd5e,
  @Libraries_Clear = 1,
  @ID = @ID_627a8792cd5e;

