-- Save MJ: Queries (core SP call only)
DECLARE @Name_72a06f7b9134 NVARCHAR(255),
@CategoryID_72a06f7b9134 UNIQUEIDENTIFIER,
@UserQuestion_72a06f7b9134 NVARCHAR(MAX),
@Description_72a06f7b9134 NVARCHAR(MAX),
@SQL_72a06f7b9134 NVARCHAR(MAX),
@TechnicalDescription_72a06f7b9134 NVARCHAR(MAX),
@OriginalSQL_72a06f7b9134 NVARCHAR(MAX),
@Feedback_72a06f7b9134 NVARCHAR(MAX),
@Status_72a06f7b9134 NVARCHAR(15),
@QualityRank_72a06f7b9134 INT,
@ExecutionCostRank_72a06f7b9134 INT,
@UsesTemplate_72a06f7b9134 BIT,
@AuditQueryRuns_72a06f7b9134 BIT,
@CacheEnabled_72a06f7b9134 BIT,
@CacheTTLMinutes_72a06f7b9134 INT,
@CacheMaxSize_72a06f7b9134 INT,
@EmbeddingVector_72a06f7b9134 NVARCHAR(MAX),
@EmbeddingModelID_72a06f7b9134 UNIQUEIDENTIFIER,
@CacheValidationSQL_72a06f7b9134 NVARCHAR(MAX),
@SQLDialectID_72a06f7b9134 UNIQUEIDENTIFIER,
@Reusable_72a06f7b9134 BIT,
@ExternalDataSourceID_72a06f7b9134 UNIQUEIDENTIFIER,
@IsMaterialized_72a06f7b9134 BIT,
@ID_72a06f7b9134 UNIQUEIDENTIFIER
SET
  @Name_72a06f7b9134 = N'Party Order Lifetime'
SET
  @CategoryID_72a06f7b9134 = 'D6586F51-1F67-4F50-BA28-7DB8A98BD4D2'
SET
  @UserQuestion_72a06f7b9134 = N'What is this person or organization''s order lifetime — counts, LTV, and years as a customer?'
SET
  @Description_72a06f7b9134 = N'Single-row party header stats: non-voided order count, open/overdue counts, lifetime gross, first order date, years as customer, and active subscription count. Used by the Person and Organization form headers so those figures are one indexed aggregate instead of four count RunViews plus extra money queries.'
SET
  @SQL_72a06f7b9134 = N'-- One-row party lifetime for the Person / Organization form header.
-- PartyKind is only used in Nunjucks branches — it never touches SQL text.
-- PartyID is quoted via sqlString.
-- Years are counted to the BUSINESS day (fnBusinessToday), not the UTC one, which turns the year
-- over on Dec 31 evening for anyone west of Greenwich.
SELECT
    ISNULL(o.OrderCount, 0) AS OrderCount,
    ISNULL(o.OpenCount, 0) AS OpenCount,
    ISNULL(o.OverdueCount, 0) AS OverdueCount,
    ISNULL(o.LifetimeValue, 0) AS LifetimeValue,
    o.FirstOrderDate,
    CASE
        WHEN o.FirstOrderDate IS NULL THEN NULL
        ELSE DATEDIFF(year, o.FirstOrderDate, bt.Today)
    END AS YearsAsCustomer,
    ISNULL(s.ActiveSubCount, 0) AS ActiveSubCount
FROM (SELECT 1 AS OneRow) AS seed
CROSS JOIN [__mj_BizAppsCommon].[fnBusinessToday]() AS bt
OUTER APPLY (
    SELECT
        COUNT(*) AS OrderCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 OR ISNULL(h.Balance, 0) > 0 THEN 1 ELSE 0 END) AS OpenCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 THEN 1 ELSE 0 END) AS OverdueCount,
        SUM(ISNULL(h.TotalGross, 0)) AS LifetimeValue,
        MIN(h.OrderDate) AS FirstOrderDate
    FROM [__mj_BizAppsOrders].vwOrderHeaders h
    WHERE h.Status <> N''Voided''
      {% if PartyKind == "person" %}
      AND h.BillToPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND h.BillToOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) o
OUTER APPLY (
    SELECT COUNT(*) AS ActiveSubCount
    FROM [__mj_BizAppsOrders].vwSubscriptions sub
    WHERE sub.Status = N''Active''
      {% if PartyKind == "person" %}
      AND sub.BeneficiaryPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND sub.HolderOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) s;
'
